insert into students (id, class_id, roll, name, edge_case_note) values (1, 1, 1, 'Nusrat Jahan Oishee', 'One failed compulsory subject on a strong average: Mathematics 29/100 fails while every other subject is an A or A+, so the GPA is cancelled to 0.00.'), (2, 1, 2, 'Tanvir Ahmed Joy', 'Practical fail with a passing theory mark: Physics theory 58/75 passes but practical 6/25 is below 8, so the subject scores 0 and cancels the GPA.'), (3, 1, 3, 'Sadia Islam Mim', 'Optional subject below the point where it helps: Higher Mathematics totals 45, grade point 2.00, so max(0, 2.00 - 2) adds nothing to the GPA.'), (4, 1, 4, 'Imran Hossain Nabil', 'Absent in a compulsory subject: Chemistry is AB, so it is grade point 0 and the overall result is F however good the rest is.'), (5, 1, 5, 'Farhana Akter Setu', 'Absent in the optional subject: Higher Mathematics is AB, contributes 0, every compulsory subject passes, so the student still gets a GPA and goes on the checking list.'), (6, 1, 6, 'Shakib Al Mahmud', 'GPA cap: six A+ compulsory subjects give 30.00 and the optional adds 3.00, so 33.00 / 6 = 5.50 is capped at 5.00.'), (7, 1, 7, 'Hasan Mridha', null), (8, 1, 8, 'Zubair Talukder', null), (9, 1, 9, 'Shafin Islam', null), (10, 1, 10, 'Rafiq Mridha', null), (11, 1, 11, 'Anika Chowdhury', null), (12, 1, 12, 'Imran Uddin', null), (13, 1, 13, 'Ishrat Talukder', null), (14, 1, 14, 'Hasan Rahman', null), (15, 1, 15, 'Jarin Jahan', null), (16, 1, 16, 'Rafiq Islam', null), (17, 1, 17, 'Rasel Chowdhury', null), (18, 1, 18, 'Farhana Sultana', null), (19, 1, 19, 'Ayesha Chowdhury', null), (20, 1, 20, 'Sumaiya Siddique', null), (21, 1, 21, 'Nabila Haque', null), (22, 1, 22, 'Farhana Sarker', null), (23, 1, 23, 'Maliha Mridha', null), (24, 1, 24, 'Ridwan Siddique', null), (25, 1, 25, 'Lamia Sarker', null), (26, 1, 26, 'Mim Akter', null), (27, 1, 27, 'Omar Talukder', null), (28, 1, 28, 'Tanvir Mridha', null), (29, 1, 29, 'Tasnim Chowdhury', null), (30, 1, 30, 'Rakib Das', null), (31, 1, 31