insert into students (id, class_id, roll, name, edge_case_note) values (33, 2, 1, 'Mehjabin Rahman Tisha', 'Exactly on both pass marks: Accounting theory 25/75 and practical 8/25 are the lowest passing marks there are, giving a total of 33 and grade point 1.00.'), (34, 2, 2, 'Rakib Uddin Sourav', 'Practical one mark short: ICT theory 70/75 is excellent but practical 7/25 misses the pass mark by one, so the subject scores 0.'), (35, 2, 3, 'Jarin Tasnim Ela', 'Optional subject grade point 1.00: Agriculture Studies totals 36, so it is on the optional checking list even though it did pass.'), (36, 2, 4, 'Sabbir Hasan Rifat', 'On all three checking lists at once: absent in the optional subject, a practical fail in Accounting, and the absence itself.'), (37, 2, 5, 'Omar Hossain', null), (38, 2, 6, 'Rakib Chowdhury', null), (39, 2, 7, 'Rithika Islam', null), (40, 2, 8, 'Rakib Siddique', null), (41, 2, 9, 'Rafiq Akter', null), (42, 2, 10, 'Nusrat Mridha', null), (43, 2, 11, 'Nusrat Sarker', null), (44, 2, 12, 'Rakib Jahan', null), (45, 2, 13, 'Farhana Talukder', null), (46, 2, 14, 'Lamia Jahan', null), (47, 2, 15, 'Lamia Akter', null), (48, 2, 16, 'Shakib Rahman', null), (49, 2, 17, 'Jarin Haque', null), (50, 2, 18, 'Naeem Uddin', null), (51, 2, 19, 'Ridwan Sarker', null), (52, 2, 20, 'Lamia Khatun', null), (53, 2, 21, 'Nusrat Haque', null), (54, 2, 22, 'Naeem Rahman', null), (55, 2, 23, 'Nusrat Bhuiyan', null), (56, 2, 24, 'Sabbir Rahman', null), (57, 2, 25, 'Anika Haque', null), (58, 2, 26, 'Naeem Siddique', null), (59, 2, 27, 'Jarin Uddin', null), (60, 2, 28, 'Tousif Islam', null), (61, 2, 29, 'Tasnim Siddique', null), (62, 2, 30, 'Sumaiya Haque', null), (63, 2, 31, 'Tousif Barua', null), (64, 2, 32, 'Anika Sultana', null);
